using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Web.Script.Serialization;

namespace CodexProxyDesktop {
 // Explicit allowlist: no raw controller replies, URLs, logs, credentials or conversation data.
 public sealed class DiagnosticRow {
  public string Utc,Session,Version,Kind,Event,Status,Reason,Mode,Group,Node,Country,Route,ChatGpt,Codex,Generic,AppResponseUtc,AppResponseNode,AppResponseGroup,FailureKind,IncidentId,WindowStartUtc,WindowEndUtc,AnonymousResponseUtc,RuleIssue,RecoveryBlock,CasePhase,CaseAction,CaseOutcome,CaseStartedUtc,CaseEndedUtc,CaseInitialNode,CaseInitialReason;
  public bool NeedsAttention;public int RecoveryAttempts;public bool Controller,TrafficFresh,AutoRecovery,RelatedFailure,UserReported;public int Connections,ServiceConnections,Failures,Delay;
  public double? Up,Down,ServiceUp,ServiceDown,RouteAgeSeconds,ProbeAgeSeconds,TrafficAgeSeconds;
 }
 public sealed class DiagnosticJournal:IDisposable {
  public readonly Automation25 Cases;readonly Dictionary<string,DateTime> eventTimes=new Dictionary<string,DateTime>();readonly object gate=new object();readonly string directory,session=Guid.NewGuid().ToString("N");readonly Func<Settings> settings;readonly int chunkBytes;readonly long? testLimit;
  bool started,closed,wasEnabled;DateTime due=DateTime.MinValue,incidentUntil=DateTime.MinValue;NetworkView lastObserved;string lastSignature="",incidentId="",error="",caseError="";
  static readonly Regex FilePattern=new Regex(@"^trace-\d{8}-\d{4}\.jsonl$",RegexOptions.CultureInvariant);
  public DiagnosticJournal(string directory,Func<Settings> settings,int chunkBytes=1024*1024,long? testLimit=null,bool resumeCase=true){this.directory=Path.GetFullPath(directory);this.settings=settings;this.chunkBytes=chunkBytes;this.testLimit=testLimit;Cases=new Automation25(settings().DiagnosticsEnabled?LoadCase():null,resumeCase);}
  public string Session {get{return session;}}public string DirectoryPath {get{return directory;}}public string Error {get{lock(gate)return error+(error.Length>0&&caseError.Length>0?"；":"")+caseError;}}
  public static int Days(Settings c){return c.DiagnosticRetentionDays<=0?14:Math.Max(1,Math.Min(90,c.DiagnosticRetentionDays));}
  public static int Megabytes(Settings c){return c.DiagnosticMaxMb<=0?100:Math.Max(5,Math.Min(500,c.DiagnosticMaxMb));}
  public static double? Age(string stamp,DateTime now){var time=Files.Date(stamp);return time==DateTime.MinValue?null:(double?)Math.Round(Math.Max(0,(now-time).TotalSeconds),1);}
  public static DiagnosticRow Snapshot(NetworkView v,Settings c,DateTime now){var status=Evidence23.Describe(v,c,v.LinkFailure,now);bool traffic=v.Controller&&v.ServiceTrafficValid&&Evidence23.Fresh(v.TrafficUtc,now,6);bool route=Evidence23.Fresh(v.RouteUtc,now,8);return new DiagnosticRow{Utc=now.ToString("o"),Mode=Safe(v.Mode),Group=Safe(v.Group),Node=Safe(v.Node),Country=Safe(v.Country),Status=status.Title,Reason=status.Detail,RuleIssue=Safe(v.RuleIssue),RecoveryBlock=Safe(NodePolicy.BlockReason(v,c)),AnonymousResponseUtc=v.AnonymousResponseUtc,Controller=v.Controller,Route=route?(v.Mode=="rule"&&!v.RuleVerified?"规则路径未确认":"已确认"):"未更新",ChatGpt=Evidence23.Target(v,true,now),Codex=Evidence23.Target(v,false,now),Generic=v.ProbeKnown&&Evidence23.Fresh(v.ProbeUtc,now,35)?(v.ProbeOk?"有响应":"探测失败"):"未确认",TrafficFresh=traffic,Up=traffic?(double?)Math.Round(v.Up,1):null,Down=traffic?(double?)Math.Round(v.Down,1):null,ServiceUp=traffic?(double?)Math.Round(v.ServiceUp,1):null,ServiceDown=traffic?(double?)Math.Round(v.ServiceDown,1):null,Connections=v.Connections,ServiceConnections=v.ServiceConnections,Failures=v.Failures,Delay=v.Delay,RouteAgeSeconds=Age(v.RouteUtc,now),ProbeAgeSeconds=Age(v.ServiceProbeUtc,now),TrafficAgeSeconds=Age(v.TrafficUtc,now),AppResponseUtc=v.AppResponseUtc,AppResponseNode=Safe(v.AppResponseNode),AppResponseGroup=Safe(v.AppResponseGroup),AutoRecovery=c.AutoSwitch,RelatedFailure=Evidence23.Relevant(v.LinkFailure,v,now),FailureKind=v.LinkFailure==null?"":v.LinkFailure.Kind,UserReported=v.LinkFailure!=null&&v.LinkFailure.UserReported};}
  public static string Safe(string value){string text=Regex.Replace(value??"",@"[\r\n\t\x00-\x1f]"," ");text=Regex.Replace(text,@"(?i)(bearer\s+|(?:token|secret|password|api[_-]?key)\s*[:=]\s*)\S+","[已遮蔽]");text=Regex.Replace(text,@"(?i)https?://\S+","[地址已省略]");text=Regex.Replace(text,@"\b(?:\d{1,3}\.){3}\d{1,3}\b","[IP已遮蔽]");return text.Length>160?text.Substring(0,160):text;}
  static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=65536};}
  void ValidateDirectory(){if(!Directory.Exists(directory))Directory.CreateDirectory(directory);if((File.GetAttributes(directory)&FileAttributes.ReparsePoint)!=0)throw new IOException("记录目录是链接，已停止写入");}
  List<FileInfo> TraceFiles(){if(!Directory.Exists(directory))return new List<FileInfo>();if((File.GetAttributes(directory)&FileAttributes.ReparsePoint)!=0)throw new IOException("记录目录是链接");return new DirectoryInfo(directory).GetFiles("trace-*.jsonl").Where(f=>FilePattern.IsMatch(f.Name)&&(f.Attributes&FileAttributes.ReparsePoint)==0).OrderBy(f=>f.Name,StringComparer.Ordinal).ToList();}
  void Trim(DateTime now,long incoming){var c=settings();long limit=testLimit??(long)Megabytes(c)*1024*1024;var files=TraceFiles();foreach(var f in files.ToArray()){DateTime day;if(DateTime.TryParseExact(f.Name.Substring(6,8),"yyyyMMdd",CultureInfo.InvariantCulture,DateTimeStyles.None,out day)&&day<now.Date.AddDays(1-Days(c))){File.Delete(f.FullName);files.Remove(f);}}
   long total=files.Sum(f=>f.Length);foreach(var f in files){if(total+incoming<=limit)break;long length=f.Length;File.Delete(f.FullName);total-=length;}if(incoming>limit)throw new IOException("单条记录超过容量限制");}
  bool Append(DiagnosticRow row,DateTime now){try{ValidateDirectory();row.Session=session;row.Version=typeof(Program).Assembly.GetName().Version.ToString();byte[] bytes=new UTF8Encoding(false).GetBytes(Json().Serialize(row)+"\n");Trim(now,bytes.Length);string prefix="trace-"+now.ToString("yyyyMMdd",CultureInfo.InvariantCulture)+"-";var today=TraceFiles().Where(f=>f.Name.StartsWith(prefix,StringComparison.Ordinal)).ToList();var last=today.LastOrDefault();int index=last==null?1:Int32.Parse(last.Name.Substring(15,4),CultureInfo.InvariantCulture);if(last!=null&&last.Length+bytes.Length>chunkBytes)index++;if(index>9999)throw new IOException("当日记录分片达到上限");string path=Path.Combine(directory,prefix+index.ToString("0000")+".jsonl");if(File.Exists(path)&&(File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new IOException("记录文件是链接");using(var stream=new FileStream(path,FileMode.Append,FileAccess.Write,FileShare.Read)){stream.Write(bytes,0,bytes.Length);}error="";return true;}catch{error="本地记录写入失败，请检查磁盘空间或目录权限；连接监控继续运行";return false;}}
  bool Ready(DateTime now){if(closed)return false;bool enabled=settings().DiagnosticsEnabled;if(!enabled){wasEnabled=false;return false;}if(!started||!wasEnabled){if(!Append(new DiagnosticRow{Utc=now.ToString("o"),Kind="session-start",Event=started?"恢复本地记录":"开始使用记录",Reason="仅保存网络诊断元数据；程序异常退出可能没有结束事件"},now))return false;started=true;due=DateTime.MinValue;lastSignature="";}if(!wasEnabled)SaveCase();wasEnabled=true;return true;}
  AutomationCase25 LoadCase(){try{string path=Path.Combine(directory,"case-state.json");if(Directory.Exists(directory)&&(File.GetAttributes(directory)&FileAttributes.ReparsePoint)==0&&File.Exists(path)&&new FileInfo(path).Length<65536&&(File.GetAttributes(path)&FileAttributes.ReparsePoint)==0){var state=Json().Deserialize<AutomationCase25>(File.ReadAllText(path));Guid id;if(state!=null&&Guid.TryParseExact(state.Id,"N",out id)&&state.StartedUtc!=null&&state.Outcome!=null&&state.HealthySinceUtc!=null&&state.LastHealthyProbeUtc!=null&&state.AttentionSinceUtc!=null)return state;}}catch{}return null;}
  void SaveCase(){if(!settings().DiagnosticsEnabled)return;try{ValidateDirectory();string path=Path.Combine(directory,"case-state.json"),temporary=path+".tmp";if(new[]{path,temporary}.Any(p=>File.Exists(p)&&(File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0))throw new IOException();File.WriteAllText(temporary,Json().Serialize(Cases.View),new UTF8Encoding(false));if(File.Exists(path))File.Replace(temporary,path,null);else File.Move(temporary,path);caseError="";}catch{caseError="故障事件状态保存失败；监测继续，重启后的事件衔接可能不完整";}}
  static void Attach(DiagnosticRow row,AutomationCase25 state,bool includeClosed=false){if(!state.Active&&!includeClosed)return;row.IncidentId=state.Id;row.CasePhase=state.Phase;row.CaseAction=state.Action;row.CaseOutcome=state.Outcome;row.CaseStartedUtc=state.StartedUtc;row.CaseEndedUtc=state.EndedUtc;row.CaseInitialNode=state.InitialNode;row.CaseInitialReason=state.InitialReason;row.RecoveryAttempts=state.RecoveryAttempts;row.NeedsAttention=state.NeedsAttention;}
  void CaseChange(NetworkView v,AutomationChange25 change,DateTime now){if(change==null)return;if(change.Kind=="incident-start"){incidentId=change.Case.Id;incidentUntil=now.AddMinutes(5);due=DateTime.MinValue;}var row=Snapshot(v,settings(),now);row.Kind=change.Kind;row.Event=Safe(change.Text);Attach(row,change.Case,true);Append(row,now);SaveCase();}
  public void MarkNotified(){lock(gate){Cases.MarkNotified();SaveCase();}}
  public void Observe(NetworkView v,DateTime now){lock(gate){if(closed)return;lastObserved=v.Copy();var change=Cases.Step(v,settings(),now);if(!Ready(now))return;CaseChange(v,change,now);var row=Snapshot(v,settings(),now);string signature=row.Status+"|"+row.Mode+"|"+row.Group+"|"+row.Node+"|"+row.Route+"|"+row.ChatGpt+"|"+row.Codex;bool changed=signature!=lastSignature;if(!changed&&now<due)return;row.Kind=changed?"status-change":"sample";row.Event=changed?"连接状态变化":"定时采样";Attach(row,Cases.View);if(row.IncidentId==null)row.IncidentId=now<=incidentUntil?incidentId:"";if(Append(row,now)){lastSignature=signature;due=now.AddSeconds(now<=incidentUntil?1:5);}}}
  public void Event(NetworkView v,string kind,string text,DateTime now,bool incident=false){lock(gate){if(closed)return;lastObserved=v.Copy();bool annotation=kind=="manual-report"&&text.Contains("仍能");bool quiet=text.Contains("暂无新流量");var change=incident&&!annotation&&!quiet?Cases.Signal(text,v.Node,now,kind=="recovery"):null;if(!Ready(now))return;CaseChange(v,change,now);var state=Cases.View;string key=(state.Active?state.Id:"")+"|"+kind+"|"+text+"|"+v.Node;DateTime previous;if(incident&&kind!="manual-report"&&eventTimes.TryGetValue(key,out previous)&&(now-previous).TotalMinutes<5)return;if(eventTimes.Count>=64)eventTimes.Clear();eventTimes[key]=now;if(incident){incidentId=state.Active?state.Id:Guid.NewGuid().ToString("N");incidentUntil=now.AddMinutes(5);due=DateTime.MinValue;}var row=Snapshot(v,settings(),now);row.Kind=kind;row.Event=Safe(text);Attach(row,state);if(row.IncidentId==null)row.IncidentId=incident?incidentId:"";row.WindowStartUtc=incident?now.AddMinutes(-5).ToString("o"):"";row.WindowEndUtc=incident?incidentUntil.ToString("o"):"";Append(row,now);SaveCase();}}
  public void Disable(DateTime now){lock(gate){if(started&&wasEnabled)Append(new DiagnosticRow{Utc=now.ToString("o"),Kind="recording-disabled",Event="用户关闭本地记录"},now);wasEnabled=false;}}
  public string Summary(){lock(gate){try{var files=TraceFiles();return (settings().DiagnosticsEnabled?"记录已开启":"记录已关闭")+" · 本次编号 "+session.Substring(0,8)+"\n"+Cases.View.Text+"\n已保存 "+files.Count+" 个分片 / "+(files.Sum(f=>f.Length)/1048576.0).ToString("0.0")+" MB · 最多 "+Days(settings())+" 天 / "+Megabytes(settings())+" MB（先达到者先清理）"+(Error.Length>0?"\n"+Error:"");}catch{return "记录目录暂不可读；连接监控继续运行";}}}
  public List<DiagnosticRow> Read(DateTime from,DateTime to,int limit=200){lock(gate){return Enumerate(from,to,true).Take(limit).ToList();}}
  IEnumerable<DiagnosticRow> Enumerate(DateTime from,DateTime to,bool newest=false){var files=TraceFiles();if(newest)files.Reverse();foreach(var file in files){DateTime day;if(DateTime.TryParseExact(file.Name.Substring(6,8),"yyyyMMdd",CultureInfo.InvariantCulture,DateTimeStyles.None,out day)&&(day.Date<from.Date||day.Date>to.Date))continue;using(var stream=new FileStream(file.FullName,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var reader=new StreamReader(stream,Encoding.UTF8)){var batch=new List<DiagnosticRow>();string line;while((line=reader.ReadLine())!=null){DiagnosticRow row=null;try{if(line.Length<=65536)row=Json().Deserialize<DiagnosticRow>(line);}catch{}if(row!=null){DateTime stamp=Files.Date(row.Utc);if(stamp>=from&&stamp<to){if(newest)batch.Add(row);else yield return row;}}}if(newest){batch.Reverse();foreach(var item in batch)yield return item;}}}}
  public int Export(string path,DateTime from,DateTime to){if(to<=from)throw new InvalidOperationException("结束日期必须晚于开始日期");string full=Path.GetFullPath(path);if(full.StartsWith(directory+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("请将诊断包保存到记录目录之外");var summaries=new StringBuilder();int count=0;bool created=false;try{using(var file=new FileStream(full,FileMode.CreateNew,FileAccess.Write,FileShare.None)){created=true;using(var archive=new ZipArchive(file,ZipArchiveMode.Create)){var entry=archive.CreateEntry("诊断记录.jsonl",CompressionLevel.Optimal);using(var writer=new StreamWriter(entry.Open(),new UTF8Encoding(false))){foreach(var row in Enumerate(from,to)){writer.WriteLine(Json().Serialize(row));count++;if(row.Kind=="incident-summary")summaries.AppendLine(Presentation.When(row.Utc)+"  事件 "+row.IncidentId+"\r\n"+row.Event+"\r\n开始时间："+Presentation.When(row.CaseStartedUtc)+"；最初原因："+row.CaseInitialReason+"\r\n开始节点："+row.CaseInitialNode+"；最后节点："+row.Node+"\r\n");}}var caseEntry=archive.CreateEntry("故障摘要.txt");using(var caseWriter=new StreamWriter(caseEntry.Open(),new UTF8Encoding(true))){var active=Cases.View;caseWriter.Write(summaries.Length==0?"所选范围尚无已结束事件。\r\n":summaries.ToString());if(active.Active&&Files.Date(active.StartedUtc)<to&&Files.Date(active.UpdatedUtc)>=from)caseWriter.Write("当前未结束事件："+active.Id+"\r\n"+active.Text+"\r\n");}var info=archive.CreateEntry("说明.txt");using(var writer=new StreamWriter(info.Open(),new UTF8Encoding(true))){writer.Write("Codex 代理管理器本地诊断包\r\n时间字段为 UTC；界面按本机时间显示。\r\n范围："+from.ToString("o")+" 至 "+to.ToString("o")+"（不含结束时刻）\r\n记录数："+count+"\r\n包含运行编号、网络采样、判断原因和事件；节点和策略组名称可能出现。\r\n未收集聊天内容、提示词、Cookie、密钥、原始控制日志或完整出口 IP。\r\n记录可能因关闭、程序退出、磁盘故障或容量清理而不连续。异常事件标注前后五分钟范围；未运行期间没有采样。\r\n字节传输和匿名探测均不能证明某轮回答完成。\r\n");}}}return count;}catch{if(created&&File.Exists(full))try{File.Delete(full);}catch{}throw;}}
  public void Dispose(){lock(gate){if(closed)return;if(started&&wasEnabled&&settings().DiagnosticsEnabled){var now=DateTime.UtcNow;CaseChange(lastObserved??new NetworkView(),Cases.Suspend(now),now);Append(new DiagnosticRow{Utc=now.ToString("o"),Kind="session-end",Event="结束使用记录"},now);}closed=true;}}
 }
}
